#define VK_USE_PLATFORM_WIN32_KHR
#include <windows.h>
#elif defined(__ANDROID__)
#define VK_USE_PLATFORM_ANDROID_KHR
#endif
#include <vulkan/vulkan.h>

#include <cstring>
#include <string>

#include <nx/runtime.h>

#include "platform.h"

namespace nx::vk {

using nx::CPU;

// A 64-bit register value as the parameter type (pointers, handles, integers, enums, flags).
template <typename T>
inline T arg(uint64_t v) {
    T r;
    std::memcpy(&r, &v, sizeof(T));
    return r;
}

// Arguments past the eighth integer/float register live in 8-byte stack slots.
template <typename T>
inline T stack_arg(CPU& c, int slot) {
    return arg<T>(ld<uint64_t>(c.x[31] + 8ull * slot));
}

template <typename T>
inline uint64_t ret_u64(T v) {
    uint64_t r = 0;
    std::memcpy(&r, &v, sizeof(T));
    return r;
}

struct Entry {
    const char* name;
    PFN_vkVoidFunction* pfn;
};
extern const Entry g_entries[];
extern const size_t g_entry_count;


}  // namespace nx::vk
